const suggestionTask=()=>({domain:'vacuum',bootId:'boot-current',roomId:'room-current',taskId:'task-current',revision:1,expiresAt:Date.now()/1000+120,options:[{id:'a'.repeat(24),action:'start',label:'Start rengøring',argsSchema:{kind:'cleaning',areas:[{id:'b'.repeat(24),label:'Køkken'},{id:'c'.repeat(24),label:'Stue'}],repeat:{min:1,max:3}}}]});
const suggestionFor=task=>({schema:'podview.robot-suggestion.v1',bootId:task.bootId,roomId:task.roomId,taskId:task.taskId,revision:1,optionId:task.options[0].id,recipeId:'d'.repeat(32),areaIds:[task.options[0].argsSchema.areas[1].id],repeat:2,expiresAt:task.expiresAt,source:'ai_recipe_selection',basis:'recent_choices'});
test('a grounded recent setup automatically prefills admitted areas and repeat without starting',()=>{
 const panel=new RobotControlPanel(),admitted=suggestionTask(),actions=[];panel.addEventListener('robot-control-action',event=>actions.push(event.detail));panel.data={task:admitted,device};const proposal=suggestionFor(admitted),form=cleaningForm(panel);assert.equal(panel.suggest(proposal),true);assert.deepEqual(form.querySelectorAll('[name=areaIds]').map(row=>row.checked),[false,true]);assert.deepEqual(form.querySelectorAll('[name=repeat]').map(row=>row.checked),[false,true,false]);assert.equal(panel.proposalButton.hidden,true);assert.equal(panel.proposalZone.children.includes(panel.proposalButton),false);assert.deepEqual(actions,[]);emit(form,'submit');assert.deepEqual(actions,[{optionId:admitted.options[0].id,args:{areaIds:proposal.areaIds,repeat:2}}]);
});
test('late proposals never overwrite a user draft or revive disconnected/readonly controls',()=>{
 const panel=new RobotControlPanel(),admitted=suggestionTask();panel.data={task:admitted,device};const form=cleaningForm(panel),first=form.querySelector('[name=areaIds]');first.checked=true;emit(form,'change');assert.equal(panel.suggest(suggestionFor(admitted)),false);assert.equal(first.checked,true);assert.equal(panel.proposalButton.hidden,true);
 panel.data={task:admitted,device};panel.disabled=true;assert.equal(panel.suggest(suggestionFor(admitted)),false);assert.equal(panel.proposalButton.hidden,true);panel.disabled=false;panel.isConnected=false;assert.equal(panel.suggest(suggestionFor(admitted)),false);
 panel.data={task:null,device};assert.equal(panel.suggest(suggestionFor(admitted)),false);assert.equal(panel.querySelectorAll('form').length,0);
});
