test('robot control keeps canonical status identity and connection while observations retain edited form',()=>{
 const panel=new RobotControlPanel();panel.data={task:task(),device:{...device,live:true,status:'cleaning',pending:true,battery:76},connected:true};
 const form=cleaningForm(panel);assert.equal(panel.observation.data.title,'Robotstøvsuger');assert.equal(panel.observation.data.resourceStatus,'cleaning');assert.equal(panel.observation.data.state,'pending');assert.equal(panel.observation.data.quietStatus,true);assert.equal(panel.observation.data.connected,true);assert.equal(panel.observation.data.text,'Rengør');
 panel.observed({...device,live:true,status:'stopped',stale:true,battery:130},{connected:false});assert.equal(cleaningForm(panel),form);assert.equal(panel.observation.data.resourceStatus,'stopped');assert.equal(panel.observation.data.state,'ready');assert.equal(panel.observation.data.connected,false);assert.equal(panel.observation.data.text,'Sidst kendt: Ingen aktiv rengøring');assert.equal(panel.observation.data.detail,'');
});


test('room tiles use buttons and repeat levels use native radios, retain IDs and never dispatch before Start',()=>{
 const panel=new RobotControlPanel(),actions=[];panel.addEventListener('robot-control-action',e=>actions.push(e.detail));panel.data={task:task(),device};
 const form=cleaningForm(panel),rooms=form.querySelectorAll('[name=areaIds]'),repeats=form.querySelectorAll('[name=repeat]');
 assert.ok(rooms.every(node=>node.tagName==='BUTTON'&&node.type==='button'));assert.ok(repeats.every(node=>node.tagName==='INPUT'&&node.type==='radio'));
 assert.equal(form.querySelectorAll('input').length,3);assert.deepEqual(rooms.map(n=>n['aria-pressed']),['false','false']);
 emit(rooms[0],'click');emit(rooms[1],'click');emit(repeats[2],'click');assert.deepEqual(rooms.map(n=>n['aria-pressed']),['true','true']);assert.deepEqual(repeats.map(selectedString),['false','false','true']);assert.deepEqual(actions,[]);
 panel.observed(device);assert.equal(cleaningForm(panel),form);assert.equal(rooms[0].value,'area-k');assert.equal(panel.querySelectorAll('svg').length,0);
 emit(form,'submit');assert.deepEqual(actions,[{optionId:'start-option',args:{areaIds:['area-k','area-s'],repeat:3}}]);
 panel.disabled=true;emit(rooms[0],'click');emit(repeats[0],'click');assert.deepEqual(rooms.map(n=>n.checked),[true,true]);assert.equal(repeats[2].checked,true);
});


test('real robot command and repeat controls bind shared Button or Segmented recipes without changing admitted IDs',()=>{
 const panel=new RobotControlPanel();panel.data={task:task(),device};const buttons=panel.querySelectorAll('button');
 assert.ok(buttons.length>0);for(const button of buttons){const family=button.getAttribute('data-kit');assert.ok(['button','chip','tile'].includes(family),button.textContent);if(button.name==='repeat'||button.name==='choiceId')assert.equal(family,'chip');}
 const original=cleaningForm(panel);panel.observed({...device,battery:50});assert.equal(cleaningForm(panel),original);assert.deepEqual(panel.querySelectorAll('[name=areaIds]').map(button=>button.value),['area-k','area-s']);
});

test('identical current task payloads retain editable rooms and repeat without reviving old task controls',()=>{
 const panel=new RobotControlPanel(),admitted=task(),actions=[];panel.addEventListener('robot-control-action',event=>actions.push(event.detail));panel.data={task:admitted,device};const form=cleaningForm(panel),rooms=form.querySelectorAll('[name=areaIds]'),repeat=form.querySelectorAll('[name=repeat]');emit(rooms[1],'click');emit(repeat[2],'click');
 panel.data={task:JSON.parse(JSON.stringify(admitted)),device:{...device,battery:77}};assert.equal(cleaningForm(panel),form);assert.equal(rooms[1].checked,true);assert.equal(repeat[2].checked,true);emit(form,'submit');assert.deepEqual(actions,[{optionId:'start-option',args:{areaIds:['area-s'],repeat:3}}]);
 panel.data={task:{...task(),taskId:'replacement'},device};emit(form,'submit');assert.equal(actions.length,1,'detached old form cannot act on replacement task even when option ID is repeated');
});

test('transport hierarchy has one current primary command, and observation changes fence the retained old command',()=>{
 const panel=new RobotControlPanel(),actions=[];panel.addEventListener('robot-control-action',event=>actions.push(event.detail));const option=(action,label)=>({id:`opaque-${action}`,action,label,argsSchema:{kind:'none'}}),admitted={domain:'vacuum',options:[option('return','Til basen'),option('pause','Pause rengøring'),option('stop','Stop rengøring'),option('resume','Fortsæt rengøring'),task().options[1]]};panel.data={task:admitted,device:{...device,status:'cleaning'}};
 const commands=panel.querySelectorAll('button').filter(node=>node.dataset.actionId),primary=commands.filter(node=>node.className.split(' ').includes('pv-primary'));assert.equal(primary.length,1);assert.equal(primary[0].textContent,'Pause rengøring');assert.equal(commands[0],primary[0]);assert.equal(commands.find(node=>node.dataset.actionId==='resume').disabled,true);assert.equal(settingForms(panel).length,1);assert.equal(panel.querySelectorAll('p').some(node=>/ikke tilbudt/.test(node.textContent)),false);
 panel.observed({...device,status:'paused'});assert.equal(primary[0].disabled,true);emit(primary[0],'click');assert.deepEqual(actions,[]);const resume=commands.find(node=>node.dataset.actionId==='resume');assert.equal(resume.disabled,false);assert.equal(resume.classList.contains('pv-primary'),true);assert.equal(resume.getAttribute('data-kit-variant'),'secondary');assert.equal(resume.dataset.kitActionRole,'context');assert.equal(primary[0].classList.contains('pv-primary'),false);assert.equal(primary[0].getAttribute('data-kit-variant'),'secondary');assert.equal(panel.transportControls.children[0],resume);assert.equal(panel.transportControls.querySelectorAll('button').filter(node=>node.dataset.actionId).length,commands.length);const retainedButtons=[...panel.transportControls.children];panel.observed({...device,status:'paused',battery:42});assert.deepEqual(panel.transportControls.children,retainedButtons);assert.equal(panel.transportControls.children.filter(node=>node.classList.contains('pv-primary')).length,1);emit(resume,'click');assert.deepEqual(actions,[{optionId:'opaque-resume',args:{}}]);
 for(const patch of [{stale:true},{pending:true}]){panel.observed({...device,status:'paused',...patch});assert.equal(resume.disabled,true);emit(resume,'click');}panel.observed({...device,status:'paused'},{connected:false});emit(resume,'click');assert.equal(actions.length,1);
});

test('expired task and local-only selection are explicit at the actual form boundary',()=>{
 const panel=new RobotControlPanel(),actions=[];panel.addEventListener('robot-control-action',event=>actions.push(event.detail));panel.data={task:{...task(),expiresAt:Date.now()/1000-1},device};const form=cleaningForm(panel);for(const room of form.querySelectorAll('[name=areaIds]'))room.checked=true;emit(form,'change');emit(form,'submit');assert.deepEqual(actions,[]);assert.ok(panel.querySelectorAll('button').every(button=>button.disabled));
 panel.data={task:task(),device,localOnly:true};const localForm=cleaningForm(panel);assert.equal(panel.cleaningSubmit.querySelector('span').textContent,'Start rengøring');assert.equal(panel.observation.data.detail,'');assert.equal(panel.value.localOnly,true);assert.ok(!localForm.querySelectorAll('p').some(node=>/Kun lokalt|Gem valg lokalt/.test(node.textContent)));assert.equal(panel.value.localOnly,true);assert.deepEqual(actions,[]);
});


