 const id=n=>String(n).repeat(24),mode={id:id(1),label:'Type',action:'set_option',settingKey:'cleaning_mode',argsSchema:{kind:'choice',current:id(2),choices:[{id:id(2),label:'vac_and_mop'},{id:id(3),label:'custom'}]}},route={id:id(4),label:'Rute',action:'set_option',settingKey:'mop_mode',argsSchema:{kind:'choice',current:id(5),choices:[{id:id(5),label:'deep'},{id:id(6),label:'standard'},{id:id(7),label:'fast'}]}},panel=new RobotControlPanel(),effects=[];panel.addEventListener('robot-control-action',e=>effects.push(e.detail));panel.data={task:{domain:'vacuum',options:[mode,route]},device:{...device,status:'cleaning',live:true},connected:true};const row=panel.settingControls.find(x=>x.option.id===route.id),inputs=row.rail.inputs;assert.deepEqual(inputs.map(i=>i.value),[id(5),id(6),id(7)]);assert.equal(inputs[0].parentNode.hidden,true);const track=row.rail.node.children.find(x=>x.className==='pv-kit-choice-options');assert.equal(track.dataset.choiceCount,'2');assert.equal(track.getAttribute('style'),'--pv-choice-columns:2');assert.match(row.rail.specialNote.textContent,/Grundig/);assert.deepEqual(effects,[]);panel.observed({...device,status:'cleaning',live:true},{settingValues:{[mode.id]:id(3)}});assert(inputs.every(i=>!i.parentNode.hidden),'custom mode does not filter');assert.equal(track.dataset.choiceCount,'3');assert.equal(track.getAttribute('style'),'--pv-choice-columns:3');panel.observed({...device,status:'cleaning',live:true},{settingValues:{[mode.id]:'unknown'}});assert(inputs.every(i=>!i.parentNode.hidden),'unknown mode does not filter');assert.equal(track.dataset.choiceCount,'3');assert.equal(track.getAttribute('style'),'--pv-choice-columns:3');assert.deepEqual(effects,[]);
