test('unrestored draft requires explicit new room and repeat before start',()=>{const admitted=task(),panel=new RobotControlPanel(),effects=[];admitted.draft={status:'not_restored'};panel.addEventListener('robot-control-action',e=>effects.push(e.detail));panel.data={task:admitted,device,connected:true};const form=cleaningForm(panel),room=form.querySelector('[name=areaIds]'),repeat=form.querySelectorAll('fieldset').find(x=>x.className.split(/\s+/).includes('repeat'));assert(repeat.querySelectorAll('input').every(x=>!x.checked));emit(room,'click');assert.equal(panel.cleaningSubmit.disabled,true);emit(form,'submit');assert.deepEqual(effects,[]);emit(repeat.querySelectorAll('input')[1],'click');assert.equal(panel.cleaningSubmit.disabled,false);emit(form,'submit');assert.equal(effects[0].args.repeat,2);});
test('retained dirty partial draft is not silently reapplied when owner cannot restore',()=>{const old=task(),panel=new RobotControlPanel();panel.data={task:old,device,connected:true};panel.cleaningDirty=true;assert.equal(panel.readCleaningDraft().repeat,1);assert.deepEqual(panel.readCleaningDraft().areaIds,[]);const replacement=structuredClone(old);replacement.draft={status:'not_restored'};panel.data={task:replacement,device,connected:true};assert.equal(panel.readCleaningDraft().repeat,null);assert.deepEqual(panel.readCleaningDraft().areaIds,[]);assert.equal(panel.cleaningSubmit.disabled,true);});
test('unrestored feedback survives unrelated host observations until explicit new selection',()=>{const admitted=task(),panel=new RobotControlPanel();admitted.draft={status:'not_restored'};panel.data={task:admitted,device,connected:true};assert.match(panel.settingsContext.textContent,/kunne ikke genskabes/);panel.observed(device,{controlFeedback:null,connected:true});assert.match(panel.settingsContext.textContent,/kunne ikke genskabes/);emit(cleaningForm(panel).querySelector('[name=areaIds]'),'click');assert.doesNotMatch(panel.settingsContext.textContent,/kunne ikke genskabes/);});
test('actual error and unknown take precedence over unrestored draft feedback and scope replacement clears it',()=>{const admitted=task(),panel=new RobotControlPanel();admitted.bootId='a';admitted.roomId='one';admitted.draft={status:'not_restored'};panel.data={task:admitted,device,connected:true};for(const state of ['error','unknown']){panel.observed(device,{controlFeedback:{text:'Aktuel handling mislykkedes',state}});assert.equal(panel.settingsContext.textContent,'Aktuel handling mislykkedes');panel.observed(device,{controlFeedback:null});assert.match(panel.settingsContext.textContent,/kunne ikke genskabes/);}const replacement=structuredClone(admitted);delete replacement.draft;replacement.bootId='b';panel.data={task:replacement,device,connected:true};panel.observed(device,{controlFeedback:null});assert.doesNotMatch(panel.settingsContext.textContent,/kunne ikke genskabes/);});
